param([Parameter(Mandatory=$true)][string]$Executable,[Parameter(Mandatory=$true)][string]$OutputDirectory,[ValidateSet('normal','gbv')][string]$Mode='normal',[switch]$ReplaceOutput)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
function Full([string]$p){[IO.Path]::GetFullPath($p)}
function Sha([string]$p){$a=[Security.Cryptography.SHA256]::Create();$s=[IO.File]::OpenRead($p);try{([BitConverter]::ToString($a.ComputeHash($s))-replace'-','').ToLowerInvariant()}finally{$s.Dispose();$a.Dispose()}}
function TextSha([string]$s){$a=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($a.ComputeHash([Text.Encoding]::UTF8.GetBytes($s)))-replace'-','').ToLowerInvariant()}finally{$a.Dispose()}}
function One([string]$text,[string]$pattern,[string]$label){$m=[regex]::Matches($text,$pattern,[Text.RegularExpressions.RegexOptions]::Multiline);if($m.Count-ne1){throw "$label count=$($m.Count)"};$m[0]}
function Snapshot([string]$repo){$paths=@(& git -C $repo diff --name-only --diff-filter=ACMRTUXB --);if($LASTEXITCODE){throw 'git diff failed'};$files=@($paths|Where-Object{$_}|Sort-Object -CaseSensitive|ForEach-Object{$p=$_.Replace('\','/');$f=Full(Join-Path $repo $_);[ordered]@{path=$p;sha256=Sha $f}});$canonical=($files|ForEach-Object{"$($_.path):$($_.sha256)`n"})-join'';[ordered]@{digest=TextSha $canonical;files=$files}}
function Measure-Pixels([Drawing.Bitmap]$a,[Drawing.Bitmap]$b,[bool]$sky){[long]$changed=0;$dark=0;$bright=0;$skyChanged=0;$skySamples=0;for($y=0;$y-lt$a.Height;$y+=2){for($x=0;$x-lt$a.Width;$x+=2){$p=$a.GetPixel($x,$y);$q=$b.GetPixel($x,$y);$u=$p.R+$p.G+$p.B;$v=$q.R+$q.G+$q.B;if([Math]::Abs($u-$v)-gt3){$changed++};if($v+6-lt$u){$dark++};if($v-gt$u+12){$bright++};if($sky-and$y-lt[int]($a.Height*.25)){$skySamples++;if([Math]::Abs($u-$v)-gt3){$skyChanged++}}}};[ordered]@{changed=$changed;darkened=$dark;brightened=$bright;skyChanged=$skyChanged;skySamples=$skySamples}}
$exe=Full $Executable;$out=Full $OutputDirectory;$repo=Full(Join-Path $PSScriptRoot '../..');$source=Full(Join-Path $repo 'engine/native/tests/SoftDirectionalShadow3DBenchmark.cpp');if(!(Test-Path -LiteralPath $exe -PathType Leaf)){throw'exe missing'};if(Test-Path -LiteralPath $out){if(!$ReplaceOutput){throw'immutable output exists'};Remove-Item -LiteralPath $out -Recurse -Force};New-Item -ItemType Directory $out|Out-Null
$stdout=Join-Path $out 'benchmark.stdout.log';$stderr=Join-Path $out 'benchmark.stderr.log';$cwd=Full(Get-Location).Path;$runId=[Guid]::NewGuid().ToString('D');$sourceBefore=Sha $source;$exeBefore=Sha $exe;$treeBefore=Snapshot $repo;$saved=[Environment]::GetEnvironmentVariable('AEVRYND_GPU_VALIDATION','Process')
try{[Environment]::SetEnvironmentVariable('AEVRYND_GPU_VALIDATION',$(if($Mode-ceq'gbv'){'1'}else{$null}),'Process');$p=Start-Process -FilePath $exe -ArgumentList @($out) -WorkingDirectory $cwd -RedirectStandardOutput $stdout -RedirectStandardError $stderr -Wait -PassThru -NoNewWindow}finally{[Environment]::SetEnvironmentVariable('AEVRYND_GPU_VALIDATION',$saved,'Process')}
if($p.ExitCode){throw "benchmark exit=$($p.ExitCode)"};$sourceAfter=Sha $source;$exeAfter=Sha $exe;$treeAfter=Snapshot $repo;if($sourceBefore-cne$sourceAfter-or$exeBefore-cne$exeAfter-or$treeBefore.digest-cne$treeAfter.digest){throw'inputs changed during run'};$text=(Get-Content -LiteralPath $stdout -Raw)-replace"`r",''
Add-Type -AssemblyName System.Drawing;$names=@('soft-directional-shadow-disabled.png','soft-directional-shadow-enabled.png','contact-shadow-disabled.png','contact-shadow-enabled.png','far-cascade-shadow-disabled.png','far-cascade-shadow-enabled.png');$captures=@();foreach($name in $names){$f=Join-Path $out $name;if(!(Test-Path -LiteralPath $f -PathType Leaf)){throw"missing $name"};$b=[Drawing.Bitmap]::FromFile($f);try{if($b.Width-ne960-or$b.Height-ne540){throw"dimensions $name"};$captures+=[ordered]@{file=$name;width=$b.Width;height=$b.Height;sha256=Sha $f}}finally{$b.Dispose()}}
function Measure-Pair([string]$off,[string]$on,[bool]$sky){$a=[Drawing.Bitmap]::FromFile((Join-Path $out $off));$b=[Drawing.Bitmap]::FromFile((Join-Path $out $on));try{Measure-Pixels $a $b $sky}finally{$a.Dispose();$b.Dispose()}}
$contact=Measure-Pair 'contact-shadow-disabled.png' 'contact-shadow-enabled.png' $true;$far=Measure-Pair 'far-cascade-shadow-disabled.png' 'far-cascade-shadow-enabled.png' $false;if($contact.darkened-lt16-or$contact.skyChanged-gt[Math]::Max(2,[int]($contact.skySamples*.001))-or$contact.brightened-gt[Math]::Max(4,[int]($contact.darkened*.05))){throw'contact semantics'};if($far.changed-lt16-or$far.darkened-lt8-or$far.brightened-gt[Math]::Max(8,[int]($far.darkened*.1))){throw'far semantics'}
$fit=One $text '^frustum_fit valid=(\d+) fallback=(\d+) reversed=(\d+) contained=(\d+) corners=(\d+) splits=([0-9eE+.,-]+)$' fit;$farRun=One $text '^far_cascade_visual submitted=(\d+) mask=(\d+) instances=(\d+) captures=(\d+)$' far;$perf=One $text '^soft_shadow_off_gpu_ns=(\d+) soft_shadow_on_gpu_ns=(\d+) gpu_delta_ns=(-?\d+) cpu_off_ns=(\d+) cpu_on_ns=(\d+) cpu_delta_ns=(-?\d+) working_set_delta_bytes=(-?\d+) tracked_delta_bytes=(-?\d+) shadow_bytes=(\d+) blocker_samples=(\d+) two_cascade_gpu_ns=(\d+) four_cascade_gpu_ns=(\d+) ordinary_cascade_regression=([0-9eE+.-]+).*contact=(\d+),(\d+)$' perf;$cache=One $text '^cache rendered/reused=([01]{4})/([01]{4}) near_move=([01]{4})/([01]{4}) reasons=([0-9,]+) sun=([01]{4})$' cache;$packs=[regex]::Matches($text,'^shadow_pack submitted=(\d+) accepted=(\d+) dropped=(\d+) packed=(\d+) groups=(\d+) bytes=(\d+) capacity=(\d+) resident=(\d+) median_cpu_ns=(\d+) p95_cpu_ns=(\d+)$',[Text.RegularExpressions.RegexOptions]::Multiline);if($packs.Count-ne2){throw'pack count'}
$splits=@($fit.Groups[6].Value.Split(',')|ForEach-Object{[double]::Parse($_,[Globalization.CultureInfo]::InvariantCulture)});$reg=[double]::Parse($perf.Groups[13].Value,[Globalization.CultureInfo]::InvariantCulture);if([int]$fit.Groups[1].Value-ne1-or[int]$fit.Groups[2].Value-ne0-or[int]$fit.Groups[4].Value-ne32-or[int]$fit.Groups[5].Value-ne32-or$splits.Count-ne4-or[int]$farRun.Groups[1].Value-ne1-or(([int]$farRun.Groups[2].Value-band8)-eq0)-or[int]$farRun.Groups[3].Value-lt2-or($Mode-ceq'normal'-and$reg-gt.05)){throw 'frustum/perf gate'}
$validation=[ordered]@{requested=0;available=0;executed=0;debug=0;passed=0;errors=0;warnings=0};if($Mode-ceq'gbv'){$g=One $text '^gbv requested=(\d+) available=(\d+) executed=(\d+) debug=(\d+) passed=(\d+) errors=(\d+) warnings=(\d+)$' gbv;$validation=[ordered]@{requested=[int]$g.Groups[1].Value;available=[int]$g.Groups[2].Value;executed=[int]$g.Groups[3].Value;debug=[int]$g.Groups[4].Value;passed=[int]$g.Groups[5].Value;errors=[int]$g.Groups[6].Value;warnings=[int]$g.Groups[7].Value};if(($validation.requested,$validation.available,$validation.executed,$validation.debug,$validation.passed)-contains0-or$validation.errors-or$validation.warnings){throw'GBV gate'}}elseif([regex]::IsMatch($text,'^gbv ',[Text.RegularExpressions.RegexOptions]::Multiline)){throw'normal emitted gbv'}
$receipt=[ordered]@{schemaVersion=1;runId=$runId;mode=$Mode;source=[ordered]@{path=$source;sha256Before=$sourceBefore;sha256After=$sourceAfter;workingTreeDigestBefore=$treeBefore.digest;workingTreeDigestAfter=$treeAfter.digest;trackedWipFiles=$treeBefore.files};executable=[ordered]@{path=$exe;sha256Before=$exeBefore;sha256After=$exeAfter};command=[ordered]@{file=$exe;arguments=@($out);workingDirectory=$cwd;gpuValidationEnvironment=$(if($Mode-ceq'gbv'){'1'}else{''})};process=[ordered]@{exitCode=[int]$p.ExitCode;stdoutFile='benchmark.stdout.log';stdoutSha256=Sha $stdout;stderrFile='benchmark.stderr.log';stderrSha256=Sha $stderr};dimensions=[ordered]@{width=960;height=540};captures=$captures;semantics=[ordered]@{contact=$contact;farCascade=$far};frustum=[ordered]@{valid=[int]$fit.Groups[1].Value;fallback=[int]$fit.Groups[2].Value;reversed=[int]$fit.Groups[3].Value;containedCorners=[int]$fit.Groups[4].Value;totalCorners=[int]$fit.Groups[5].Value;splits=$splits};farCascade=[ordered]@{submitted=[int]$farRun.Groups[1].Value;mask=[int]$farRun.Groups[2].Value;instances=[int]$farRun.Groups[3].Value;captures=[int]$farRun.Groups[4].Value};performance=[ordered]@{softOffGpuNanoseconds=[long]$perf.Groups[1].Value;softOnGpuNanoseconds=[long]$perf.Groups[2].Value;twoCascadeGpuNanoseconds=[long]$perf.Groups[11].Value;fourCascadeGpuNanoseconds=[long]$perf.Groups[12].Value;fourCascadeRegression=$reg;maximumRegression=.05;passed=$true};cacheMemory=[ordered]@{stableRendered=$cache.Groups[1].Value;stableReused=$cache.Groups[2].Value;movedRendered=$cache.Groups[3].Value;movedReused=$cache.Groups[4].Value;workingSetDeltaBytes=[long]$perf.Groups[7].Value;trackedDeltaBytes=[long]$perf.Groups[8].Value;shadowBytes=[long]$perf.Groups[9].Value;pack10kResidentBytes=[long]$packs[0].Groups[8].Value;pack100kResidentBytes=[long]$packs[1].Groups[8].Value};gpuValidation=$validation}
$receipt|ConvertTo-Json -Depth 10|Set-Content -LiteralPath (Join-Path $out 'shadow-capture-receipt.json') -Encoding UTF8;Write-Host "SHADOW_CAPTURE_PASS mode=$Mode runId=$runId"
